def envio_v1(peso, zona, urgente):          # código heredado: funciona, pero cuesta leerlo
    if zona == "local":
        if peso <= 1:
            p = 4.5
        else:
            if peso <= 5:
                p = 6.9
            else:
                p = 6.9 + (peso - 5) * 0.8
    elif zona == "nacional":
        if peso <= 1:
            p = 7.5
        else:
            if peso <= 5:
                p = 11.0
            else:
                p = 11.0 + (peso - 5) * 1.2
    else:
        raise ValueError(zona)
    if urgente:
        p = p * 1.5
    return round(p, 2)


TARIFAS = {  # zona: (hasta 1 kg, hasta 5 kg, por kg adicional)
    "local": (4.5, 6.9, 0.8),
    "nacional": (7.5, 11.0, 1.2),
}


def envio_v2(peso: float, zona: str, urgente: bool = False) -> float:
    try:
        hasta_1, hasta_5, extra = TARIFAS[zona]
    except KeyError:
        raise ValueError(zona) from None
    precio = hasta_1 if peso <= 1 else hasta_5 + max(0, peso - 5) * extra
    return round(precio * (1.5 if urgente else 1), 2)


