import re

NUMERO = re.compile(r"\d+(?:\.\d+)?")


def evaluar(texto):
    tokens = re.findall(r"\d+(?:\.\d+)?|[-+*/()]", texto) + ["FIN"]
    pos = 0

    def mirar():
        return tokens[pos]

    def consumir(esperado=None):
        nonlocal pos
        token = tokens[pos]
        if esperado is not None and token != esperado:
            raise SyntaxError(f"se esperaba {esperado!r} y llegó {token!r}")
        pos += 1
        return token

    def expr():  # expr := termino (("+" | "-") termino)*
        valor = termino()
        while mirar() in ("+", "-"):
            if consumir() == "+":
                valor += termino()
            else:
                valor -= termino()
        return valor

    def termino():  # termino := factor (("*" | "/") factor)*
        valor = factor()
        while mirar() in ("*", "/"):
            if consumir() == "*":
                valor *= factor()
            else:
                valor /= factor()
        return valor

    def factor():  # factor := "-" factor | NUM | "(" expr ")"
        token = mirar()
        if token == "-":
            consumir()
            return -factor()
        if token == "(":
            consumir("(")
            valor = expr()
            consumir(")")
            return valor
        if NUMERO.fullmatch(token):
            return float(consumir())
        raise SyntaxError(f"token inesperado {token!r}")

    resultado = expr()
    consumir("FIN")
    return resultado


for texto in ["2 + 3 * 4", "(2 + 3) * 4", "8 - 3 - 2", "-(1 + 1) * 3"]:
