import itertools
from collections import Counter


def leer(lineas):  # fuente: en la vida real, un archivo abierto
    for numero, linea in enumerate(lineas, start=1):
        yield numero, linea.rstrip("\n")


def parsear(pares):
    for numero, linea in pares:
        partes = linea.split()
        if len(partes) == 3:  # nivel servicio mensaje
            yield {"linea": numero, "nivel": partes[0], "servicio": partes[1]}


def solo(nivel, registros):
    return (r for r in registros if r["nivel"] == nivel)


