import sqlite3
from dataclasses import dataclass


@dataclass(frozen=True)
class Nota:
    texto: str
    id: int | None = None


class RepositorioNotas:  # capa de datos: aquí vive todo el SQL
    def __init__(self, conexion: sqlite3.Connection):
        self._con = conexion
        self._con.execute("CREATE TABLE IF NOT EXISTS notas (id INTEGER PRIMARY KEY, texto TEXT NOT NULL)")

    def agregar(self, nota: Nota) -> Nota:
        with self._con:  # commit al salir; rollback si hay excepción
            cursor = self._con.execute("INSERT INTO notas (texto) VALUES (?)", (nota.texto,))
        return Nota(nota.texto, cursor.lastrowid)

    def todas(self) -> list[Nota]:
        return [Nota(texto, id_) for id_, texto in self._con.execute("SELECT id, texto FROM notas ORDER BY id")]


def main(argv: list[str], repo: RepositorioNotas) -> int:  # capa de interfaz: sin SQL
    orden, *resto = argv
    if orden == "nueva":
        nota = repo.agregar(Nota(" ".join(resto)))
        print(f"Nota #{nota.id} guardada")
    elif orden == "lista":
        for nota in repo.todas():
            print(f"#{nota.id}: {nota.texto}")
    else:
        print(f"Orden desconocida: {orden}")
        return 2
    return 0


repo = RepositorioNotas(sqlite3.connect(":memory:"))  # inyectamos la dependencia
main(["nueva", "Estudiar", "asyncio"], repo)
main(["nueva", "Preparar", "el", "portafolio"], repo)
main(["lista"], repo)

