import json
from urllib.parse import parse_qs

RUTAS = {"/", "/salud", "/saludo"}
TEXTO = "text/plain; charset=utf-8"


def _responder(start_response, estado, cuerpo, tipo=TEXTO, extra=()):
    datos = cuerpo.encode("utf-8")
    cabeceras = [("Content-Type", tipo), ("Content-Length", str(len(datos))), *extra]
    start_response(estado, cabeceras)
    return [datos]


def app(environ, start_response):
    """Aplicación WSGI con las rutas /, /salud y /saludo."""
    metodo = environ["REQUEST_METHOD"]
    ruta = environ.get("PATH_INFO", "/")
    if ruta not in RUTAS:
        return _responder(start_response, "404 Not Found", "No encontrado")
    if metodo != "GET":
        return _responder(start_response, "405 Method Not Allowed", "Método no permitido",
                          extra=[("Allow", "GET")])
    if ruta == "/":
        return _responder(start_response, "200 OK", "Bienvenido a la API")
    if ruta == "/salud":
        return _responder(start_response, "200 OK", json.dumps({"estado": "ok"}),
                          tipo="application/json")
    parametros = parse_qs(environ.get("QUERY_STRING", ""))
    nombre = parametros.get("nombre", ["mundo"])[0]
    return _responder(start_response, "200 OK", f"Hola, {nombre}")

