def llamar(aplicacion, metodo="GET", ruta="/", query=""):
    """Simula un servidor WSGI: devuelve (estado, cabeceras en minúsculas, cuerpo str)."""
    environ = {"REQUEST_METHOD": metodo, "SCRIPT_NAME": "", "PATH_INFO": ruta, "QUERY_STRING": query}
    setup_testing_defaults(environ)
    capturado = {}

    def start_response(status, headers, exc_info=None):
        capturado["status"] = status
        capturado["headers"] = {k.lower(): v for k, v in headers}
        return lambda datos: None

    resultado = aplicacion(environ, start_response)
    try:
        cuerpo = b"".join(resultado)
    finally:
        if hasattr(resultado, "close"):
            resultado.close()
    return capturado["status"], capturado["headers"], cuerpo.decode("utf-8")

