import re

_CABECERA = re.compile(
    r"(?P<tipo>[A-Za-z]+)"
    r"(?:\((?P<ambito>[^()\s]+)\))?"
    r"(?P<rompe>!)?"
    r": (?P<descripcion>\S.*)"
)
_PIE_RUPTURA = re.compile(r"BREAKING[ -]CHANGE: ")


def parsear_commit(mensaje):
    """Analiza un mensaje de commit convencional."""
    lineas = mensaje.strip().splitlines()
    if not lineas:
        raise ValueError("El mensaje de commit está vacío")
    cabecera = _CABECERA.fullmatch(lineas[0].strip())
    if cabecera is None:
        raise ValueError(f"Cabecera no convencional: {lineas[0]!r}")
    tipo = cabecera["tipo"].lower()
    rompe = cabecera["rompe"] is not None or any(
        _PIE_RUPTURA.match(linea) for linea in lineas[1:]
    )
    if rompe:
        incremento = "major"
    elif tipo == "feat":
        incremento = "minor"
    elif tipo == "fix":
        incremento = "patch"
    else:
        incremento = None
    return {
        "tipo": tipo,
        "ambito": cabecera["ambito"],
        "rompe": rompe,
        "descripcion": cabecera["descripcion"].strip(),
        "incremento": incremento,
    }

