import operator

OPERACIONES = {
    "+": operator.add,
    "-": operator.sub,
    "*": operator.mul,
    "/": operator.truediv,
}


def _numero(elemento):
    try:
        return int(elemento)
    except ValueError:
        pass
    try:
        return float(elemento)
    except ValueError:
        raise ValueError(f"Elemento desconocido: {elemento!r}") from None


def evaluar_rpn(expresion):
    """Evalúa una expresión en notación polaca inversa."""
    pila = []
    for elemento in expresion.split():
        if elemento in OPERACIONES:
            if len(pila) < 2:
                raise ValueError(f"Faltan operandos para {elemento!r}")
            derecho = pila.pop()
            izquierdo = pila.pop()
            pila.append(OPERACIONES[elemento](izquierdo, derecho))
        else:
            pila.append(_numero(elemento))
    if len(pila) != 1:
        raise ValueError(f"La expresión deja {len(pila)} valores en la pila (se esperaba 1)")
    return pila[0]

