import json


async def _responder_json(send, estado, datos):
    cuerpo = json.dumps(datos, ensure_ascii=False).encode("utf-8")
    await send({
        "type": "http.response.start",
        "status": estado,
        "headers": [
            (b"content-type", b"application/json"),
            (b"content-length", str(len(cuerpo)).encode("ascii")),
        ],
    })
    await send({"type": "http.response.body", "body": cuerpo})


async def _leer_cuerpo(receive):
    trozos = []
    while True:
        mensaje = await receive()
        trozos.append(mensaje.get("body", b""))
        if not mensaje.get("more_body", False):
            return b"".join(trozos)


async def app(scope, receive, send):
    """Aplicación ASGI con soporte de lifespan y dos rutas HTTP."""
    if scope["type"] == "lifespan":
        while True:
            mensaje = await receive()
            if mensaje["type"] == "lifespan.startup":
                await send({"type": "lifespan.startup.complete"})
            elif mensaje["type"] == "lifespan.shutdown":
                await send({"type": "lifespan.shutdown.complete"})
                return
    elif scope["type"] == "http":
        ruta = (scope["method"], scope["path"])
        if ruta == ("GET", "/"):
            await _responder_json(send, 200, {"mensaje": "hola"})
        elif ruta == ("POST", "/eco"):
            cuerpo = await _leer_cuerpo(receive)
            await _responder_json(send, 200, {"bytes": len(cuerpo), "texto": cuerpo.decode("utf-8")})
        else:
            await _responder_json(send, 404, {"error": "no encontrado"})
    else:
        raise NotImplementedError(f"Tipo de scope no soportado: {scope['type']}")

