from graphlib import TopologicalSorter


def niveles(dependencias):
    """Agrupa las tareas en niveles ejecutables en paralelo."""
    ts = TopologicalSorter(dependencias)
    ts.prepare()  # lanza CycleError si hay ciclos
    resultado = []
    while ts.is_active():
        listas = sorted(ts.get_ready())
        resultado.append(listas)
        ts.done(*listas)
    return resultado


def tiempo_minimo(dependencias, duraciones):
    """Duración del camino crítico con paralelismo ilimitado."""
    ts = TopologicalSorter(dependencias)
    for tarea in duraciones:
        ts.add(tarea)  # las tareas sueltas también cuentan
    fin = {}
    for tarea in ts.static_order():
        if tarea not in duraciones:
            raise KeyError(f"Falta la duración de {tarea!r}")
        inicio = max((fin[previa] for previa in dependencias.get(tarea, ())), default=0)
        fin[tarea] = inicio + duraciones[tarea]
    return max(fin.values(), default=0)

