import re
from dataclasses import dataclass
from datetime import date


class ErrorValidacion(ValueError):
    def __init__(self, errores):
        self.errores = errores
        super().__init__("; ".join(f"{campo}: {mensaje}" for campo, mensaje in errores.items()))


@dataclass(frozen=True)
class Campo:
    tipo: type = str
    requerido: bool = True
    minimo: float | None = None
    maximo: float | None = None
    patron: str | None = None


CONVERSORES = {str: str, int: int, float: float, date: date.fromisoformat}


def _validar_campo(texto, campo):
    """Devuelve (valor, None) si es válido o (None, mensaje) si no."""
    try:
        valor = CONVERSORES[campo.tipo](texto)
    except ValueError:
        return None, f"debe ser {campo.tipo.__name__}"
    if campo.patron is not None and not re.fullmatch(campo.patron, texto):
        return None, "formato inválido"
    if campo.minimo is not None and valor < campo.minimo:
        return None, f"debe ser >= {campo.minimo}"
    if campo.maximo is not None and valor > campo.maximo:
        return None, f"debe ser <= {campo.maximo}"
    return valor, None


def validar(fila, esquema):
    """Convierte y valida una fila (dict de str) según el esquema."""
    errores = {nombre: "campo desconocido" for nombre in fila if nombre not in esquema}
    resultado = {}
    for nombre, campo in esquema.items():
        texto = (fila.get(nombre) or "").strip()
        if not texto:
            if campo.requerido:
                errores[nombre] = "obligatorio"
            else:
                resultado[nombre] = None
            continue
        valor, error = _validar_campo(texto, campo)
        if error:
            errores[nombre] = error
        else:
            resultado[nombre] = valor
    if errores:
        raise ErrorValidacion(errores)
    return resultado


def validar_lote(filas, esquema):
    """Valida muchas filas: devuelve (validas, [(numero, errores), ...])."""
    validas, errores = [], []
    for numero, fila in enumerate(filas, start=1):
        try:
            validas.append(validar(fila, esquema))
        except ErrorValidacion as error:
            errores.append((numero, error.errores))
    return validas, errores

