exercises.solution:
import statistics


class NoAjustadoError(ValueError, AttributeError):
    """Se usó el modelo antes de ajustarlo (como sklearn.exceptions.NotFittedError)."""


class RegresionLineal:
    """Regresión lineal simple con la interfaz fit/predict/score de scikit-learn."""

    def fit(self, X, y):
        X, y = list(X), list(y)
        if len(X) != len(y):
            raise ValueError(f"X tiene {len(X)} valores e y tiene {len(y)}")
        if len(X) < 2:
            raise ValueError("Se necesitan al menos dos puntos")
        try:
            pendiente, ordenada = statistics.linear_regression(X, y)
        except statistics.StatisticsError as error:
            raise ValueError(f"No se puede ajustar: {error}") from error
        self.coef_ = pendiente
        self.intercept_ = ordenada
        return self

    def _comprobar_ajustado(self):
        if not hasattr(self, "coef_"):
            raise NoAjustadoError("Llama a fit() antes de predict() o score()")

    def predict(self, X):
        self._comprobar_ajustado()
        return [self.coef_ * x + self.intercept_ for x in X]

    def score(self, X, y):
        self._comprobar_ajustado()
        y = list(y)
        predicciones = self.predict(X)
        media = statistics.fmean(y)
        ss_res = sum((real - pred) ** 2 for real, pred in zip(y, predicciones, strict=True))
        ss_tot = sum((real - media) ** 2 for real in y)
        if ss_tot == 0:
            return 1.0 if ss_res == 0 else 0.0
        return 1 - ss_res / ss_tot

    def __repr__(self):
        return "RegresionLineal()"

