import re


class ErrorJSON(ValueError):
    def __init__(self, mensaje, pos):
        super().__init__(f"{mensaje} (posición {pos})")
        self.pos = pos


ESCAPES = {'"': '"', "\\": "\\", "/": "/", "b": "\b", "f": "\f", "n": "\n", "r": "\r", "t": "\t"}
NUMERO = re.compile(r"-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?")
HEXADECIMAL = set("0123456789abcdefABCDEF")
LITERALES = (("true", True), ("false", False), ("null", None))


class _Parser:
    def __init__(self, texto):
        self.texto = texto
        self.pos = 0

    def error(self, mensaje):
        raise ErrorJSON(mensaje, self.pos)

    def actual(self):
        return self.texto[self.pos] if self.pos < len(self.texto) else ""

    def saltar_espacios(self):
        while self.pos < len(self.texto) and self.texto[self.pos] in " \t\n\r":
            self.pos += 1

    def esperar(self, caracter):
        if self.actual() != caracter:
            self.error(f"se esperaba {caracter!r}")
        self.pos += 1

    def valor(self):
        self.saltar_espacios()
        c = self.actual()
        if c == "":
            self.error("fin de texto inesperado")
        if c == "{":
            return self.objeto()
        if c == "[":
            return self.lista()
        if c == '"':
            return self.cadena()
        if c == "-" or c.isascii() and c.isdigit():
            return self.numero()
        for palabra, valor in LITERALES:
            if self.texto.startswith(palabra, self.pos):
                self.pos += len(palabra)
                return valor
        self.error(f"valor inesperado {c!r}")

    def objeto(self):
        self.esperar("{")
        resultado = {}
        self.saltar_espacios()
        if self.actual() == "}":
            self.pos += 1
            return resultado
        while True:
            self.saltar_espacios()
            if self.actual() != '"':
                self.error("se esperaba una clave entre comillas dobles")
            clave = self.cadena()
            self.saltar_espacios()
            self.esperar(":")
            resultado[clave] = self.valor()
            self.saltar_espacios()
            if self.actual() == ",":
                self.pos += 1
                continue
            self.esperar("}")
            return resultado

    def lista(self):
        self.esperar("[")
        elementos = []
        self.saltar_espacios()
        if self.actual() == "]":
            self.pos += 1
            return elementos
        while True:
            elementos.append(self.valor())
            self.saltar_espacios()
            if self.actual() == ",":
                self.pos += 1
                continue
            self.esperar("]")
            return elementos

    def cadena(self):
        self.esperar('"')
        partes = []
        while True:
            if self.pos >= len(self.texto):
                self.error("cadena sin cerrar")
            c = self.texto[self.pos]
            if c == '"':
                self.pos += 1
                return "".join(partes)
            if c == "\\":
                self.pos += 1
                escape = self.actual()
                if escape in ESCAPES:
                    partes.append(ESCAPES[escape])
                    self.pos += 1
                elif escape == "u":
                    digitos = self.texto[self.pos + 1:self.pos + 5]
                    if len(digitos) != 4 or not set(digitos) <= HEXADECIMAL:
                        self.error("escape \\u inválido")
                    partes.append(chr(int(digitos, 16)))
                    self.pos += 5
                else:
                    self.error("secuencia de escape inválida")
            elif ord(c) < 32:
                self.error("carácter de control sin escapar")
            else:
                partes.append(c)
                self.pos += 1

    def numero(self):
        coincidencia = NUMERO.match(self.texto, self.pos)
        if coincidencia is None:
            self.error("número inválido")
        lexema = coincidencia.group()
        self.pos = coincidencia.end()
        if any(c in lexema for c in ".eE"):
            return float(lexema)
        return int(lexema)


def parsear_json(texto):
    """Convierte un texto JSON en el valor Python equivalente."""
    parser = _Parser(texto)
    valor = parser.valor()
    parser.saltar_espacios()
    if parser.pos != len(texto):
        parser.error("datos extra tras el valor")
    return valor

