exercises.solution:
import sqlite3


class ErrorMigracion(Exception):
    def __init__(self, version, mensaje):
        super().__init__(f"Migración {version}: {mensaje}")
        self.version = version


def version_actual(conexion):
    """Devuelve el número de la última migración aplicada."""
    return conexion.execute("PRAGMA user_version").fetchone()[0]


def migrar(conexion, migraciones):
    """Aplica las migraciones pendientes y devuelve la versión final."""
    actual = version_actual(conexion)
    if actual > len(migraciones):
        raise ErrorMigracion(actual, "la base de datos es más nueva que el código")
    for numero in range(actual + 1, len(migraciones) + 1):
        try:
            for sentencia in migraciones[numero - 1]:
                conexion.execute(sentencia)
            # PRAGMA no admite parámetros "?": el formato :d garantiza un entero.
            conexion.execute(f"PRAGMA user_version = {numero:d}")
            conexion.commit()
        except sqlite3.Error as error:
            conexion.rollback()
            raise ErrorMigracion(numero, str(error)) from error
    return version_actual(conexion)

