from collections import deque
from datetime import timedelta


def alertas(eventos, ventana, umbral):
    """Devuelve un iterador con los instantes en que empieza cada pico de errores."""
    if umbral < 1:
        raise ValueError("umbral debe ser >= 1")
    if not isinstance(ventana, timedelta) or ventana <= timedelta(0):
        raise ValueError("ventana debe ser un timedelta positivo")
    return _alertas(eventos, ventana, umbral)


def _alertas(eventos, ventana, umbral):
    errores = deque()  # momentos de los ERROR dentro de la ventana
    en_alerta = False
    anterior = None
    for momento, nivel in eventos:
        if anterior is not None and momento < anterior:
            raise ValueError(f"Evento desordenado: {momento} llega después de {anterior}")
        anterior = momento
        while errores and errores[0] <= momento - ventana:
            errores.popleft()
        if nivel == "ERROR":
            errores.append(momento)
        if len(errores) >= umbral:
            if not en_alerta:
                en_alerta = True
                yield momento
        else:
            en_alerta = False

