exercises.solution:
import math
import operator
import re
from dataclasses import dataclass
from typing import NamedTuple


# ---------------------------------------------------------------- errores
class ErrorCalculo(Exception):
    """Base de todos los errores de la calculadora."""


class ErrorLexico(ErrorCalculo):
    def __init__(self, mensaje, pos):
        super().__init__(f"{mensaje} (posición {pos})")
        self.pos = pos


class ErrorSintaxis(ErrorCalculo):
    def __init__(self, mensaje, pos):
        super().__init__(f"{mensaje} (posición {pos})")
        self.pos = pos


class ErrorEvaluacion(ErrorCalculo):
    """División por cero, variable o función desconocida, dominio inválido..."""


# ---------------------------------------------------------------- tokens
class Token(NamedTuple):
    tipo: str      # "NUM", "NOMBRE", "OP", "(", ")", ",", "=" o "FIN"
    valor: object  # int | float si es NUM; el texto del token en los demás; "" en FIN
    pos: int       # índice del primer carácter del token en el texto


# ---------------------------------------------------------------- AST
@dataclass(frozen=True)
class Num:
    valor: int | float


@dataclass(frozen=True)
class Var:
    nombre: str


@dataclass(frozen=True)
class Unario:
    op: str
    operando: object


@dataclass(frozen=True)
class Binario:
    op: str
    izq: object
    der: object


@dataclass(frozen=True)
class Llamada:
    funcion: str
    args: tuple


@dataclass(frozen=True)
class Asignacion:
    nombre: str
    valor: object


CONSTANTES = {"pi": math.pi, "e": math.e}
FUNCIONES = {"sqrt": math.sqrt, "abs": abs, "max": max, "min": min, "round": round}


# ================================================================ Fase 1
_PATRON = re.compile(r"""
    (?P<ESPACIO>\s+)
  | (?P<NUM>\d+\.\d*|\.\d+|\d+)
  | (?P<NOMBRE>[^\W\d]\w*)
  | (?P<OP>[-+*/%^])
  | (?P<SIMBOLO>[(),=])
""", re.VERBOSE)


def tokenizar(texto):
    """Convierte el texto en una lista de Token terminada en FIN."""
    tokens = []
    pos = 0
    while pos < len(texto):
        coincidencia = _PATRON.match(texto, pos)
        if coincidencia is None:
            raise ErrorLexico(f"carácter inesperado {texto[pos]!r}", pos)
        tipo, lexema = coincidencia.lastgroup, coincidencia.group()
        if tipo == "NUM":
            tokens.append(Token("NUM", float(lexema) if "." in lexema else int(lexema), pos))
        elif tipo == "SIMBOLO":
            tokens.append(Token(lexema, lexema, pos))
        elif tipo != "ESPACIO":
            tokens.append(Token(tipo, lexema, pos))
        pos = coincidencia.end()
    tokens.append(Token("FIN", "", len(texto)))
    return tokens


# ================================================================ Fase 2
class _Parser:
    """Un método por regla de la gramática; self.i apunta al token actual."""

    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    @property
    def actual(self):
        return self.tokens[self.i]

    def avanzar(self):
        token = self.tokens[self.i]
        self.i += 1
        return token

    def es(self, tipo, *valores):
        token = self.actual
        return token.tipo == tipo and (not valores or token.valor in valores)

    def fallar(self, mensaje):
        token = self.actual
        encontrado = "el final" if token.tipo == "FIN" else repr(token.valor)
        raise ErrorSintaxis(f"{mensaje}; se encontró {encontrado}", token.pos)

    def esperar(self, tipo):
        if not self.es(tipo):
            self.fallar(f"se esperaba {tipo!r}")
        return self.avanzar()

    def sentencia(self):
        if self.es("NOMBRE") and self.tokens[self.i + 1].tipo == "=":
            nombre = self.avanzar().valor
            self.avanzar()  # el "="
            nodo = Asignacion(nombre, self.expr())
        else:
            nodo = self.expr()
        if not self.es("FIN"):
            self.fallar("se esperaba el final de la expresión")
        return nodo

    def expr(self):
        nodo = self.termino()
        while self.es("OP", "+", "-"):          # bucle → asociatividad izquierda
            op = self.avanzar().valor
            nodo = Binario(op, nodo, self.termino())
        return nodo

    def termino(self):
        nodo = self.factor()
        while self.es("OP", "*", "/", "%"):
            op = self.avanzar().valor
            nodo = Binario(op, nodo, self.factor())
        return nodo

    def factor(self):
        if self.es("OP", "+", "-"):
            op = self.avanzar().valor
            return Unario(op, self.factor())
        return self.potencia()

    def potencia(self):
        base = self.atomo()
        if self.es("OP", "^"):                  # recursión → asociatividad derecha
            self.avanzar()
            return Binario("^", base, self.factor())
        return base

    def atomo(self):
        token = self.actual
        if token.tipo == "NUM":
            self.avanzar()
            return Num(token.valor)
        if token.tipo == "NOMBRE":
            self.avanzar()
            if not self.es("("):
                return Var(token.valor)
            self.avanzar()
            args = []
            if not self.es(")"):
                args.append(self.expr())
                while self.es(","):
                    self.avanzar()
                    args.append(self.expr())
            self.esperar(")")
            return Llamada(token.valor, tuple(args))
        if token.tipo == "(":
            self.avanzar()
            nodo = self.expr()
            self.esperar(")")
            return nodo
        self.fallar("se esperaba un número, un nombre o '('")


def parsear(texto):
    """Devuelve el AST de una sentencia (expresión o asignación)."""
    return _Parser(tokenizar(texto)).sentencia()


# ================================================================ Fase 3
_BINARIOS = {
    "+": operator.add, "-": operator.sub, "*": operator.mul,
    "/": operator.truediv, "%": operator.mod, "^": operator.pow,
}


def evaluar(nodo, entorno):
    """Evalúa un nodo del AST con las variables de 'entorno'."""
    match nodo:
        case Num(valor):
            return valor
        case Var(nombre):
            if nombre in CONSTANTES:
                return CONSTANTES[nombre]
            if nombre in entorno:
                return entorno[nombre]
            raise ErrorEvaluacion(f"variable no definida: {nombre}")
        case Unario(op, operando):
            valor = evaluar(operando, entorno)
            return -valor if op == "-" else +valor
        case Binario(op, izq, der):
            a, b = evaluar(izq, entorno), evaluar(der, entorno)
            try:
                resultado = _BINARIOS[op](a, b)
            except ZeroDivisionError:
                raise ErrorEvaluacion("división por cero") from None
            except OverflowError:
                raise ErrorEvaluacion("resultado demasiado grande") from None
            if isinstance(resultado, complex):
                raise ErrorEvaluacion("el resultado no es un número real")
            return resultado
        case Llamada(nombre, args):
            if nombre not in FUNCIONES:
                raise ErrorEvaluacion(f"función desconocida: {nombre}")
            valores = [evaluar(arg, entorno) for arg in args]
            try:
                return FUNCIONES[nombre](*valores)
            except (TypeError, ValueError, OverflowError) as error:
                raise ErrorEvaluacion(f"{nombre}: {error}") from error
        case Asignacion(nombre, valor):
            if nombre in CONSTANTES or nombre in FUNCIONES:
                raise ErrorEvaluacion(f"no se puede reasignar {nombre!r}")
            resultado = evaluar(valor, entorno)
            entorno[nombre] = resultado
            return resultado
        case _:
            raise TypeError(f"nodo desconocido: {nodo!r}")


# ================================================================ Fase 4
class Calculadora:
    def __init__(self):
        self.variables = {}

    def ejecutar(self, linea):
        return evaluar(parsear(linea), self.variables)


def repl():
    """Bucle interactivo: lee, evalúa, imprime."""
    calculadora = Calculadora()
    while True:
        try:
            linea = input("calc> ")
        except EOFError:
            break
        if linea.strip() == "salir":
            break
        if not linea.strip():
            continue
        try:
            print("=", calculadora.ejecutar(linea))
        except ErrorCalculo as error:
            print(f"Error: {error}")


if __name__ == "__main__":
    repl()  # al pulsar «Ejecutar»: escribe una expresión por línea en la entrada

