import argparse
import sqlite3
import sys
from dataclasses import dataclass, replace
from datetime import date
from enum import IntEnum


class Prioridad(IntEnum):
    BAJA = 1
    MEDIA = 2
    ALTA = 3


class ErrorValidacion(ValueError):
    """Datos de una tarea no válidos."""


class TareaNoEncontrada(LookupError):
    """No existe una tarea con ese id."""



# ================================================================ Fase 1
@dataclass(frozen=True)
class Tarea:
    titulo: str
    prioridad: Prioridad = Prioridad.MEDIA
    vence: date | None = None
    hecha: bool = False
    id: int | None = None

    def __post_init__(self):
        titulo = self.titulo.strip() if isinstance(self.titulo, str) else ""
        if not 1 <= len(titulo) <= 80:
            raise ErrorValidacion("el título debe tener entre 1 y 80 caracteres")
        try:
            prioridad = Prioridad(self.prioridad)
        except ValueError:
            raise ErrorValidacion(f"prioridad inválida: {self.prioridad!r}") from None
        object.__setattr__(self, "titulo", titulo)
        object.__setattr__(self, "prioridad", prioridad)

    def esta_vencida(self, hoy):
        return not self.hecha and self.vence is not None and self.vence < hoy


def formatear(tarea):
    marca = "x" if tarea.hecha else " "
    texto = f"[{marca}] #{tarea.id} {tarea.prioridad.name:<5} {tarea.titulo}"
    if tarea.vence is not None:
        texto += f" (vence {tarea.vence.isoformat()})"
    return texto


# ================================================================ Fase 2
class RepositorioTareas:
    _COLUMNAS = "id, titulo, prioridad, vence, hecha"

    def __init__(self, conexion):
        self._con = conexion
        with self._con:
            self._con.execute(
                """CREATE TABLE IF NOT EXISTS tareas (
                       id INTEGER PRIMARY KEY AUTOINCREMENT,
                       titulo TEXT NOT NULL,
                       prioridad INTEGER NOT NULL,
                       vence TEXT,
                       hecha INTEGER NOT NULL DEFAULT 0
                   )"""
            )

    @staticmethod
    def _a_tarea(fila):
        id_tarea, titulo, prioridad, vence, hecha = fila
        return Tarea(titulo, Prioridad(prioridad),
                     date.fromisoformat(vence) if vence else None, bool(hecha), id_tarea)

    def agregar(self, tarea):
        vence = tarea.vence.isoformat() if tarea.vence else None
        with self._con:
            cursor = self._con.execute(
                "INSERT INTO tareas (titulo, prioridad, vence, hecha) VALUES (?, ?, ?, ?)",
                (tarea.titulo, int(tarea.prioridad), vence, int(tarea.hecha)),
            )
        return replace(tarea, id=cursor.lastrowid)

    def obtener(self, id_tarea):
        fila = self._con.execute(
            f"SELECT {self._COLUMNAS} FROM tareas WHERE id = ?", (id_tarea,)
        ).fetchone()
        if fila is None:
            raise TareaNoEncontrada(f"no existe la tarea #{id_tarea}")
        return self._a_tarea(fila)

    def listar(self, *, pendientes=False):
        filtro = "WHERE hecha = 0" if pendientes else ""
        filas = self._con.execute(
            f"SELECT {self._COLUMNAS} FROM tareas {filtro} "
            "ORDER BY hecha, prioridad DESC, vence IS NULL, vence, id"
        )
        return [self._a_tarea(fila) for fila in filas]

    def completar(self, id_tarea):
        with self._con:
            cursor = self._con.execute("UPDATE tareas SET hecha = 1 WHERE id = ?", (id_tarea,))
        if cursor.rowcount == 0:
            raise TareaNoEncontrada(f"no existe la tarea #{id_tarea}")
        return self.obtener(id_tarea)

    def eliminar(self, id_tarea):
        with self._con:
            cursor = self._con.execute("DELETE FROM tareas WHERE id = ?", (id_tarea,))
        if cursor.rowcount == 0:
            raise TareaNoEncontrada(f"no existe la tarea #{id_tarea}")

    def resumen(self, hoy):
        tareas = self.listar()
        hechas = sum(t.hecha for t in tareas)
        return {
            "total": len(tareas),
            "pendientes": len(tareas) - hechas,
            "hechas": hechas,
            "vencidas": sum(t.esta_vencida(hoy) for t in tareas),
        }


# ================================================================ Fase 3
def _fecha(texto):
    try:
        return date.fromisoformat(texto)
    except ValueError:
        raise argparse.ArgumentTypeError(f"fecha inválida: {texto!r} (usa AAAA-MM-DD)") from None


def crear_parser():
    parser = argparse.ArgumentParser(prog="tareas", description="Gestor de tareas")
    sub = parser.add_subparsers(dest="comando", required=True)

    nueva = sub.add_parser("nueva", help="crea una tarea")
    nueva.add_argument("titulo")
    nueva.add_argument("-p", "--prioridad", choices=["baja", "media", "alta"], default="media")
    nueva.add_argument("--vence", type=_fecha)

    lista = sub.add_parser("lista", help="muestra las tareas")
    lista.add_argument("--pendientes", action="store_true")

    for nombre in ("hecha", "borrar"):
        orden = sub.add_parser(nombre)
        orden.add_argument("id", type=int)

    sub.add_parser("resumen", help="muestra un resumen")
    return parser


def main(argv, repo, hoy=None):
    args = crear_parser().parse_args(argv)  # SystemExit(2) si el uso es incorrecto
    try:
        match args.comando:
            case "nueva":
                tarea = Tarea(args.titulo, Prioridad[args.prioridad.upper()], args.vence)
                print("Creada:", formatear(repo.agregar(tarea)))
            case "lista":
                tareas = repo.listar(pendientes=args.pendientes)
                for tarea in tareas:
                    print(formatear(tarea))
                if not tareas:
                    print("No hay tareas")
            case "hecha":
                print("Completada:", formatear(repo.completar(args.id)))
            case "borrar":
                repo.eliminar(args.id)
                print(f"Borrada #{args.id}")
            case "resumen":
                r = repo.resumen(hoy or date.today())
                print(f"Total: {r['total']} | Pendientes: {r['pendientes']} | "
                      f"Hechas: {r['hechas']} | Vencidas: {r['vencidas']}")
    except (ErrorValidacion, TareaNoEncontrada) as error:
        print(f"Error: {error}", file=sys.stderr)
        return 1
    return 0

if __name__ == "__main__":
    # En tu terminal sería: raise SystemExit(main(sys.argv[1:], RepositorioTareas(sqlite3.connect("tareas.db"))))
    demo = RepositorioTareas(sqlite3.connect(":memory:"))
    for orden in (["nueva", "Pagar la luz", "-p", "alta", "--vence", "2026-10-01"],
                  ["nueva", "Leer Fluent Python", "-p", "baja"], ["hecha", "2"], ["lista"], ["resumen"]):
        print("$ tareas", " ".join(orden))
        main(orden, demo)

