import csv
import json
import re
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation


class ErrorValidacion(ValueError):
    """Datos de producto o de movimiento no válidos."""


class StockInsuficiente(Exception):
    def __init__(self, sku, disponible, solicitado):
        super().__init__(f"{sku}: hay {disponible} y se piden {solicitado}")
        self.sku = sku
        self.disponible = disponible
        self.solicitado = solicitado


COLUMNAS = ("sku", "nombre", "precio", "stock", "categoria")

SKU = re.compile(r"[A-Z]{3}-\d{4}")
CENTAVO = Decimal("0.01")


# ================================================================ Fase 1
@dataclass(slots=True)
class Producto:
    sku: str
    nombre: str
    precio: Decimal
    stock: int = 0
    categoria: str = "general"

    def __post_init__(self):
        if not isinstance(self.sku, str) or not SKU.fullmatch(self.sku):
            raise ErrorValidacion(f"sku inválido: {self.sku!r} (formato AAA-0000)")
        self.nombre = self.nombre.strip()
        if not self.nombre:
            raise ErrorValidacion("nombre vacío")
        self.precio = self._validar_precio(self.precio)
        if type(self.stock) is not int or self.stock < 0:
            raise ErrorValidacion(f"stock inválido: {self.stock!r}")
        self.categoria = self.categoria.strip().lower()
        if not self.categoria:
            raise ErrorValidacion("categoria vacía")

    @staticmethod
    def _validar_precio(precio):
        if isinstance(precio, float) or not isinstance(precio, (Decimal, int, str)):
            raise ErrorValidacion("precio: usa Decimal, int o str, nunca float")
        try:
            precio = Decimal(precio)
        except InvalidOperation:
            raise ErrorValidacion(f"precio inválido: {precio!r}") from None
        if not precio.is_finite() or precio < 0:
            raise ErrorValidacion(f"precio inválido: {precio}")
        if precio != precio.quantize(CENTAVO):
            raise ErrorValidacion(f"precio con más de 2 decimales: {precio}")
        return precio.quantize(CENTAVO)

    @property
    def valor(self):
        return self.precio * self.stock


# ================================================================ Fase 2
class Inventario:
    def __init__(self):
        self._productos = {}
        self.movimientos = []

    def agregar(self, producto):
        if producto.sku in self._productos:
            raise ErrorValidacion(f"sku repetido: {producto.sku}")
        self._productos[producto.sku] = producto

    def __len__(self):
        return len(self._productos)

    def __contains__(self, sku):
        return sku in self._productos

    def __getitem__(self, sku):
        return self._productos[sku]

    def __iter__(self):
        return iter(sorted(self._productos.values(), key=lambda p: p.sku))

    @staticmethod
    def _validar_cantidad(cantidad):
        if type(cantidad) is not int or cantidad <= 0:
            raise ErrorValidacion(f"cantidad inválida: {cantidad!r}")

    def entrada(self, sku, cantidad):
        self._validar_cantidad(cantidad)
        self[sku].stock += cantidad
        self.movimientos.append((sku, "entrada", cantidad))

    def salida(self, sku, cantidad):
        self._validar_cantidad(cantidad)
        producto = self[sku]
        if cantidad > producto.stock:
            raise StockInsuficiente(sku, producto.stock, cantidad)
        producto.stock -= cantidad
        self.movimientos.append((sku, "salida", cantidad))

    def valor_total(self):
        return sum((p.valor for p in self._productos.values()), Decimal("0.00"))

    def bajo_stock(self, umbral):
        return sorted((p for p in self if p.stock < umbral), key=lambda p: (p.stock, p.sku))


# ================================================================ Fase 3
def cargar_csv(ruta):
    inventario, errores = Inventario(), []
    with open(ruta, encoding="utf-8", newline="") as archivo:
        lector = csv.DictReader(archivo)
        faltan = [c for c in COLUMNAS if c not in (lector.fieldnames or [])]
        if faltan:
            raise ErrorValidacion(f"faltan columnas: {', '.join(faltan)}")
        for fila in lector:
            try:
                try:
                    stock = int(fila["stock"])
                except ValueError:
                    raise ErrorValidacion(f"stock no es un entero: {fila['stock']!r}") from None
                inventario.agregar(Producto(fila["sku"], fila["nombre"], fila["precio"],
                                            stock, fila["categoria"]))
            except ErrorValidacion as error:
                errores.append((lector.line_num, str(error)))
    return inventario, errores


# ================================================================ Fase 4
def _a_dict(producto):
    return {"sku": producto.sku, "nombre": producto.nombre, "precio": str(producto.precio),
            "stock": producto.stock, "categoria": producto.categoria}


def exportar_json(inventario, ruta):
    datos = {"productos": [_a_dict(p) for p in inventario]}
    with open(ruta, "w", encoding="utf-8") as archivo:
        json.dump(datos, archivo, ensure_ascii=False, indent=2)


def importar_json(ruta):
    with open(ruta, encoding="utf-8") as archivo:
        datos = json.load(archivo)
    inventario = Inventario()
    for item in datos["productos"]:
        inventario.agregar(Producto(**item))
    return inventario


# ================================================================ Fase 5
def informe_por_categoria(inventario):
    filas = {}
    for producto in inventario:
        fila = filas.setdefault(producto.categoria, {"categoria": producto.categoria, "productos": 0,
                                                     "unidades": 0, "valor": Decimal("0.00")})
        fila["productos"] += 1
        fila["unidades"] += producto.stock
        fila["valor"] += producto.valor
    return sorted(filas.values(), key=lambda f: (-f["valor"], f["categoria"]))


def exportar_informe_csv(inventario, ruta):
    with open(ruta, "w", encoding="utf-8", newline="") as archivo:
        escritor = csv.DictWriter(archivo, fieldnames=["categoria", "productos", "unidades", "valor"])
        escritor.writeheader()
        escritor.writerows(informe_por_categoria(inventario))

if __name__ == "__main__":
    demo = Inventario()
    demo.agregar(Producto("PAP-0001", "Cuaderno", "2.50", 40, "papelería"))
    demo.agregar(Producto("ELE-0100", "Mouse", "19.99", 8, "electrónica"))
    demo.salida("PAP-0001", 5)
    for fila in informe_por_categoria(demo):
        print(fila)
    print("Valor total:", demo.valor_total())

