import asyncio
from collections.abc import Awaitable, Callable
from dataclasses import dataclass, field
from graphlib import CycleError, TopologicalSorter


class ErrorPlanificacion(Exception):
    """Plan inválido: trabajo duplicado, dependencia desconocida o ciclo."""


@dataclass
class Trabajo:
    nombre: str
    funcion: Callable[[dict], Awaitable]  # async def f(entradas: dict) -> resultado
    depende_de: tuple[str, ...] = ()
    reintentos: int = 0
    timeout: float | None = None


@dataclass
class Informe:
    resultados: dict = field(default_factory=dict)  # nombre -> valor devuelto
    fallidos: dict = field(default_factory=dict)    # nombre -> última excepción
    omitidos: set = field(default_factory=set)      # no ejecutados por dependencias fallidas
    orden: list = field(default_factory=list)       # nombres en orden de finalización con éxito
    intentos: dict = field(default_factory=dict)    # nombre -> intentos realizados



class Planificador:
    def __init__(self, max_concurrencia=2):
        if max_concurrencia < 1:
            raise ValueError("max_concurrencia debe ser >= 1")
        self.max_concurrencia = max_concurrencia
        self._trabajos = {}

    # ============================================================ Fase 1
    def agregar(self, nombre, funcion, *, depende_de=(), reintentos=0, timeout=None):
        if nombre in self._trabajos:
            raise ErrorPlanificacion(f"trabajo duplicado: {nombre}")
        if reintentos < 0:
            raise ValueError("reintentos debe ser >= 0")
        self._trabajos[nombre] = Trabajo(nombre, funcion, tuple(depende_de), reintentos, timeout)
        return self

    def validar(self):
        for trabajo in self._trabajos.values():
            for dependencia in trabajo.depende_de:
                if dependencia not in self._trabajos:
                    raise ErrorPlanificacion(f"{trabajo.nombre} depende de {dependencia}, que no existe")
        grafo = {nombre: trabajo.depende_de for nombre, trabajo in self._trabajos.items()}
        try:
            return list(TopologicalSorter(grafo).static_order())
        except CycleError as error:
            ciclo = " -> ".join(error.args[1])
            raise ErrorPlanificacion(f"dependencias circulares: {ciclo}") from error

    # ============================================================ Fases 2-4
    async def ejecutar(self):
        orden = self.validar()
        informe = Informe()
        semaforo = asyncio.Semaphore(self.max_concurrencia)
        tareas = {}
        async with asyncio.TaskGroup() as grupo:
            for nombre in orden:  # orden topológico: las dependencias ya tienen tarea
                trabajo = self._trabajos[nombre]
                tareas[nombre] = grupo.create_task(
                    self._correr(trabajo, tareas, informe, semaforo), name=nombre
                )
        return informe

    async def _correr(self, trabajo, tareas, informe, semaforo):
        """Devuelve True si el trabajo terminó con éxito. Nunca lanza Exception."""
        exitos = [await tareas[dependencia] for dependencia in trabajo.depende_de]
        if not all(exitos):
            informe.omitidos.add(trabajo.nombre)
            return False
        entradas = {dependencia: informe.resultados[dependencia] for dependencia in trabajo.depende_de}
        ultimo_error = None
        async with semaforo:  # la plaza se pide DESPUÉS de esperar a las dependencias
            for intento in range(1, trabajo.reintentos + 2):
                informe.intentos[trabajo.nombre] = intento
                try:
                    async with asyncio.timeout(trabajo.timeout):  # None = sin límite
                        valor = await trabajo.funcion(entradas)
                except Exception as error:  # CancelledError (BaseException) sí se propaga
                    ultimo_error = error
                else:
                    informe.resultados[trabajo.nombre] = valor
                    informe.orden.append(trabajo.nombre)
                    return True
        informe.fallidos[trabajo.nombre] = ultimo_error
        return False


async def demo():
    def trabajo(valor, segundos=0.05):
        async def f(entradas):
            await asyncio.sleep(segundos)
            return valor + sum(entradas.values())
        return f

    plan = (Planificador(max_concurrencia=2)
            .agregar("descargar", trabajo(1))
            .agregar("lint", trabajo(10))
            .agregar("tests", trabajo(100), depende_de=["descargar"])
            .agregar("informe", trabajo(1000), depende_de=["tests", "lint"]))
    informe = await plan.ejecutar()
    print("orden:", informe.orden)
    print("resultado final:", informe.resultados.get("informe"))


if __name__ == "__main__":
    await demo()  # en un script normal: asyncio.run(demo())

